#!/usr/bin/env python3
"""Filter, select, and sort a CSV file."""
import argparse
import csv
import sys


def parse_args():
    parser = argparse.ArgumentParser(prog="csvq")
    parser.add_argument("--where", action="append", default=[], metavar="COL=VALUE")
    parser.add_argument("--select", metavar="COL,COL,...")
    parser.add_argument("--sort", metavar="COL")
    parser.add_argument("--numeric", action="store_true")
    parser.add_argument("--desc", action="store_true")
    parser.add_argument("FILE")
    return parser.parse_args()


def write_row(values):
    # Keep the format deliberately minimal and make line endings consistent.
    rendered = []
    for value in values:
        value = str(value)
        if any(ch in value for ch in ',"\r\n'):
            value = '"' + value.replace('"', '""') + '"'
        rendered.append(value)
    sys.stdout.write(",".join(rendered) + "\n")


def main():
    args = parse_args()
    try:
        with open(args.FILE, "r", encoding="utf-8", newline="") as source:
            reader = csv.reader(source)
            try:
                header = next(reader)
            except StopIteration:
                header = []
            rows = list(reader)
    except (OSError, UnicodeError, csv.Error) as exc:
        print(f"csvq: {exc}", file=sys.stderr)
        return 2

    # Header names map to their first occurrence if the input has duplicates.
    positions = {}
    for index, name in enumerate(header):
        positions.setdefault(name, index)

    conditions = []
    for expression in args.where:
        if "=" not in expression:
            print("csvq: --where requires COL=VALUE", file=sys.stderr)
            return 2
        name, value = expression.split("=", 1)
        conditions.append((name, value))

    selected = header if args.select is None else args.select.split(",")
    named_columns = [name for name, _ in conditions]
    if args.select is not None:
        named_columns.extend(selected)
    if args.sort is not None:
        named_columns.append(args.sort)
    for name in named_columns:
        if name not in positions:
            print(f"csvq: unknown column: {name}", file=sys.stderr)
            return 2

    filtered = [
        row for row in rows
        if all(row[positions[name]] == value for name, value in conditions)
    ]

    if args.sort is not None:
        sort_index = positions[args.sort]
        if args.numeric:
            numeric_rows = []
            nonnumeric_rows = []
            for original_index, row in enumerate(filtered):
                try:
                    number = float(row[sort_index])
                except (ValueError, OverflowError):
                    nonnumeric_rows.append((original_index, row))
                else:
                    numeric_rows.append((number, original_index, row))
            numeric_rows.sort(key=lambda item: item[0], reverse=args.desc)
            # Nonnumeric values are always last and retain their input order.
            filtered = [item[2] for item in numeric_rows] + [item[1] for item in nonnumeric_rows]
        else:
            filtered.sort(key=lambda row: row[sort_index], reverse=args.desc)

    write_row(selected)
    for row in filtered:
        write_row([row[positions[name]] for name in selected])
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
